1	import { z } from 'zod';
2	import { buildUrl, isWriteMethod, parseResponse } from './http-internal';
3	
4	/**
5	 * Browser-safe HTTP client. Sends the PUBLISHABLE key.
6	 *
7	 * Use this from:
8	 *   - Client components
9	 *   - Hooks / event handlers
10	 *   - ANY code that might run in the browser bundle
11	 *
12	 * For endpoints that require the secret key, use `httpServer` from
13	 * `./http-server` instead — importing that module from client code throws.
14	 *
15	 * Env:
16	 *   NEXT_PUBLIC_API_BASE_URL         — e.g. https://api.example.com/v1
17	 *   NEXT_PUBLIC_API_PUBLISHABLE_KEY  — safe to expose to browsers
18	 *
19	 * `RequestOptions` / `HttpMethod` are global (see `types/http-service.d.ts`).
20	 */
21	
22	export { ApiError, envelope } from './http-internal';
23	
24	class HttpClient {
25	  constructor(
26	    private readonly baseUrl: string,
27	    private readonly apiKey: string,
28	  ) {}
29	
30	  private buildHeaders(args: {
31	    method: HttpMethod;
32	    hasBody: boolean;
33	    idempotencyKey?: string;
34	    extra?: HeadersInit;
35	  }): HeadersInit {
36	    const headers: Record<string, string> = { Accept: 'application/json' };
37	
38	    if (args.hasBody) {
39	      headers['Content-Type'] = 'application/json';
40	    }
41	
42	    if (this.apiKey) {
43	      headers['x-easy-api-key'] = this.apiKey;
44	    }
45	
46	    if (args.idempotencyKey && isWriteMethod(args.method)) {
47	      headers['Idempotency-Key'] = args.idempotencyKey;
48	    }
49	
50	    return { ...headers, ...args.extra };
51	  }
52	
53	  private async request<TBody = unknown>(
54	    options: RequestOptions<TBody>,
55	  ): Promise<unknown> {
56	    const { path, method = 'GET', query, body, headers, idempotencyKey, signal, cache, next } = options;
57	    const hasBody = body !== undefined && method !== 'GET' && method !== 'DELETE';
58	
59	    const response = await fetch(buildUrl(this.baseUrl, path, query), {
60	      method,
61	      signal,
62	      cache,
63	      next,
64	      headers: this.buildHeaders({ method, hasBody, idempotencyKey, extra: headers }),
65	      body: hasBody ? JSON.stringify(body) : undefined,
66	    });
67	
68	    return parseResponse(response);
69	  }
70	
71	  private async send<TSchema extends z.ZodTypeAny, TBody = unknown>(
72	    schema: TSchema,
73	    options: RequestOptions<TBody>,
74	  ): Promise<z.infer<TSchema>> {
75	    const raw = await this.request<TBody>(options);
76	    return schema.parse(raw) as z.infer<TSchema>;
77	  }
78	
79	  get<TSchema extends z.ZodTypeAny>(
80	    schema: TSchema,
81	    options: Omit<RequestOptions, 'method' | 'body'>,
82	  ) {
83	    return this.send(schema, { ...options, method: 'GET' });
84	  }
85	
86	  post<TSchema extends z.ZodTypeAny, TBody = unknown>(
87	    schema: TSchema,
88	    options: Omit<RequestOptions<TBody>, 'method'>,
89	  ) {
90	    return this.send<TSchema, TBody>(schema, { ...options, method: 'POST' });
91	  }
92	
93	  put<TSchema extends z.ZodTypeAny, TBody = unknown>(
94	    schema: TSchema,
95	    options: Omit<RequestOptions<TBody>, 'method'>,
96	  ) {
97	    return this.send<TSchema, TBody>(schema, { ...options, method: 'PUT' });
98	  }
99	
100	  patch<TSchema extends z.ZodTypeAny, TBody = unknown>(
101	    schema: TSchema,
102	    options: Omit<RequestOptions<TBody>, 'method'>,
103	  ) {
104	    return this.send<TSchema, TBody>(schema, { ...options, method: 'PATCH' });
105	  }
106	
107	  delete<TSchema extends z.ZodTypeAny>(
108	    schema: TSchema,
109	    options: Omit<RequestOptions, 'method' | 'body'>,
110	  ) {
111	    return this.send(schema, { ...options, method: 'DELETE' });
112	  }
113	}
114	
115	export const http = new HttpClient(
116	  process.env.NEXT_PUBLIC_API_BASE_URL ?? '',
117	  process.env.NEXT_PUBLIC_API_PUBLISHABLE_KEY ?? '',
118	);
