import { getAllProjects } from 'lib/firebase/server-actions';
import { AdminGuard } from './_fragments/AdminGuard';
import { ProjectList } from './_fragments/ProjectList';

export async function generateMetadata() {
  return {
    title: 'Projects List | Beni Entertainment Capital',
    description: 'Projects List | Beni Entertainment Capital',
  };
}

export default async function ProjectsListPage() {
  // Fetch all projects from Firestore on the server side
  const projects = await getAllProjects();

  return (
    <AdminGuard>
      <ProjectList projects={projects} />
    </AdminGuard>
  );
}

