import { Routes } from 'const/Routes';
import { getProjectById } from 'lib/firebase/server-actions';
import { ArrowLeft } from 'lucide-react';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { AdminGuard } from '../_fragments/AdminGuard';
import { SetupProjectPageContent } from './_fragments/SetupProjectPageContent';

export async function generateMetadata() {
  return {
    title: 'Single Project | Beni Entertainment Capital',
    description: 'Single Project | Beni Entertainment Capital',
  };
}

interface SetupProjectPageProps {
  params: Promise<{ id: string }>;
}

export default async function SetupProjectPage({
  params,
}: SetupProjectPageProps) {
  const { id } = await params;

  // If the id is 'new', we're creating a new project
  const isNewProject = id === 'new';

  let project: (Project & { id: string }) | null = null;

  if (!isNewProject) {
    // Fetch existing project from Firestore
    project = await getProjectById(id);

    // If project doesn't exist, show 404
    if (!project) {
      notFound();
    }
  }

  return (
    <AdminGuard>
      <main className="p-20 lg:p-40 bg-off-white w-full h-full">
        <Link
          href={Routes.ADMIN_PROJECT_LIST}
          className="flex items-center gap-8 text-sm text-gray-500 mb-20">
          <ArrowLeft width={16} height={16} />
          Back to Projects
        </Link>

        <div className="mb-8">
          <h1 className="text-3xl font-bold">
            {isNewProject
              ? 'Setup New Project'
              : `Edit Project: ${project?.name}`}
          </h1>
          <p className="text-muted-foreground mt-2">
            {isNewProject
              ? 'Add a new project to Firebase Firestore'
              : `Editing project with ID: ${project?.id}`}
          </p>
        </div>
        <SetupProjectPageContent project={project} isNewProject={isNewProject} />
      </main>
    </AdminGuard>
  );
}

