'use client';

import { FC, useState } from 'react';
import { SetupProjectForm } from './SetupProjectForm';
import { Tabs } from './Tabs';
import { Returns } from './Returns';
import { AdminTransactions } from './AdminTransactions';

interface SetupProjectPageContentProps {
  project?: (Project & { id: string }) | null;
  isNewProject: boolean;
}

export const SetupProjectPageContent: FC<SetupProjectPageContentProps> = ({
  project,
  isNewProject,
}) => {
  const [activeTab, setActiveTab] = useState<
    'setup' | 'returns' | 'transactions'
  >('setup');

  return (
    <>
      <Tabs
        activeTab={activeTab}
        onTabChange={setActiveTab}
        isNewProject={isNewProject}
      />

      {activeTab === 'setup' && <SetupProjectForm project={project} />}

      {activeTab === 'returns' && !isNewProject && project && (
        <Returns project={project} />
      )}

      {activeTab === 'transactions' && !isNewProject && project && (
        <AdminTransactions project={project} />
      )}
    </>
  );
};

