import { z } from 'zod';
import { envelope, http } from '../../shared/services/http-client';

export const ProductPriceIntervalSchema = z.enum([
  'day',
  'week',
  'month',
  'year',
]);

export const ProductPricePricingModelSchema = z.enum([
  'per_unit',
  'tiered_volume',
  'tiered_graduated',
  'package',
  'metered',
  'flat_rate',
]);

export const ProductPriceTaxBehaviorSchema = z.enum(['inclusive', 'exclusive']);

// Upstream accepts a fixed list of ISO-4217 currency codes. Validating only
// "non-empty 3-letter string" keeps the service forgiving — the upstream API
// is the source of truth for which codes are actually accepted.
export const ProductPriceCurrencySchema = z.string().length(3);

export const CreateProductPriceBodySchema = z.object({
  product_id: z.string().min(1),
  recurring: z.boolean().optional(),
  currency: ProductPriceCurrencySchema.optional(),
  unit_amount: z.number().nonnegative().optional(),
  interval: ProductPriceIntervalSchema.optional(),
  interval_count: z.number().int().min(1).optional(),
  pricing_model: ProductPricePricingModelSchema.optional(),
  trial_period_days: z.number().int().min(0).optional(),
  metadata: z.record(z.string(), z.unknown()).optional(),
  active: z.boolean().optional(),
  tax_behavior: ProductPriceTaxBehaviorSchema.optional(),
  description: z.string().optional(),
});

export const ProductPriceSchema = z.object({
  id: z.string(),
  product_id: z.string(),
  currency: z.string().optional(),
  unit_amount: z.number().optional(),
  recurring: z.boolean().optional(),
  active: z.boolean().optional(),
  tax_behavior: ProductPriceTaxBehaviorSchema.optional(),
  description: z.string().optional(),
  metadata: z.record(z.string(), z.unknown()).optional(),
  created_at: z.string(),
});

export type ProductPriceInterval = z.infer<typeof ProductPriceIntervalSchema>;
export type ProductPricePricingModel = z.infer<
  typeof ProductPricePricingModelSchema
>;
export type ProductPriceTaxBehavior = z.infer<
  typeof ProductPriceTaxBehaviorSchema
>;
export type CreateProductPriceBody = z.infer<
  typeof CreateProductPriceBodySchema
>;
export type ProductPrice = z.infer<typeof ProductPriceSchema>;

export const productPricesService = {
  /** POST /v1/api/product-prices/ — Create a price for an existing product. */
  create: async (
    body: CreateProductPriceBody,
    opts: { idempotencyKey?: string } = {},
  ) => {
    const res = await http.post(envelope(ProductPriceSchema), {
      path: '/v1/api/product-prices/',
      body: CreateProductPriceBodySchema.parse(body),
      idempotencyKey: opts.idempotencyKey,
    });

    return res.data;
  },
};

