import { envelope, httpServer } from '../../shared/services/http-server';
import {
  CreateProductPriceBodySchema,
  ProductPriceSchema,
} from './product-prices.service';

export type {
  ProductPriceInterval,
  ProductPricePricingModel,
  ProductPriceTaxBehavior,
  CreateProductPriceBody,
  ProductPrice,
} from './product-prices.service';

export const productPricesServerService = {
  /** POST /v1/api/product-prices/ — Create a price for an existing product. */
  create: async (
    body: CreateProductPriceBody,
    opts: { idempotencyKey?: string } = {},
  ) => {
    const parsedBody = CreateProductPriceBodySchema.parse(body);

    const raw = await httpServer.post<z.ZodUnknown, CreateProductPriceBody>(
      z.unknown(),
      {
        path: '/v1/api/product-prices/',
        body: parsedBody,
        idempotencyKey: opts.idempotencyKey,
      },
    );

    const res = envelope(ProductPriceSchema).parse(raw);
    return res.data;
  },
};

