/**
 * Types for our own Route Handler at `/api/product-prices`.
 *
 * These describe the INTERNAL contract between the admin dashboard and our
 * backend, not the external 3rd-party product-prices API (see `services/`).
 *
 * The route handler resolves the upstream `product_id` from the project
 * (Firestore) so callers only pass `projectId` plus price configuration.
 */

import * as z from 'zod';

const CURRENCY_PATTERN = /^[A-Z]{3}$/;

export const CreateProductPriceRequestSchema = z.object({
  projectId: z.string().min(1),
  currency: z.string().regex(CURRENCY_PATTERN, 'Expected ISO-4217 code (e.g. USD)'),
  unit_amount: z.number().nonnegative(),
  recurring: z.boolean().optional(),
  active: z.boolean().optional(),
  tax_behavior: z.enum(['inclusive', 'exclusive']).optional(),
  description: z.string().max(500).optional(),
  /**
   * Stable per-attempt key the client can send so retries don't create
   * duplicate prices. Optional — if omitted, the server generates a fresh UUID
   * and retries are NOT idempotent.
   */
  idempotencyKey: z.string().min(1).max(255).optional(),
});

export const CreateProductPriceDataSchema = z.object({
  id: z.string(),
  product_id: z.string(),
  currency: z.string().optional(),
  unit_amount: z.number().optional(),
  recurring: z.boolean().optional(),
  active: z.boolean().optional(),
  tax_behavior: z.enum(['inclusive', 'exclusive']).optional(),
  description: z.string().optional(),
  created_at: z.string(),
});

export const CreateProductPriceResponseSchema = z.object({
  success: z.literal(true),
  timestamp: z.string(),
  message: z.string().optional(),
  data: CreateProductPriceDataSchema,
});

export const CreateProductPriceErrorSchema = z.object({
  error: z.object({
    code: z.string(),
    message: z.string(),
    details: z.unknown().optional(),
  }),
});

export type CreateProductPriceRequest = z.infer<
  typeof CreateProductPriceRequestSchema
>;
export type CreateProductPriceData = z.infer<
  typeof CreateProductPriceDataSchema
>;
export type CreateProductPriceResponse = z.infer<
  typeof CreateProductPriceResponseSchema
>;
export type CreateProductPriceErrorResponse = z.infer<
  typeof CreateProductPriceErrorSchema
>;

